window.NOTES={"version":43,"chapters":[{"number":1,"title":"信息技术与计算机文化","summary":"计算机发展、信息表示、硬件、软件与计算机系统的基础概念。","sections":[{"id":"1.1","title":"信息与信息技术"},{"id":"1.2","title":"计算机技术概论"},{"id":"1.3","title":"计算机中信息的表示"},{"id":"1.4","title":"计算机系统"},{"id":"1.5","title":"微型计算机系统"}]},{"number":2,"title":"Windows 10 操作系统","summary":"操作系统特征、Windows界面、文件管理、系统设置与维护。","sections":[{"id":"2.1","title":"操作系统概述"},{"id":"2.2","title":"Windows 10 基础"},{"id":"2.3","title":"文件和文件夹管理"},{"id":"2.4","title":"控制面板"},{"id":"2.5","title":"Windows 10 的系统维护"},{"id":"2.6","title":"Windows 10 的实用工具"}]},{"number":3,"title":"字处理软件 Word 2016","summary":"文档编辑、格式排版、表格、图文混排与长文档功能。","sections":[{"id":"3.1","title":"使用 Office 2016 应用程序"},{"id":"3.2","title":"Word 2016 的基本操作"},{"id":"3.3","title":"文档格式化与排版"},{"id":"3.4","title":"表格制作"},{"id":"3.5","title":"图文混排"},{"id":"3.6","title":"文档的保护与打印"},{"id":"3.7","title":"Word 2016 的高级应用"}]},{"number":4,"title":"电子表格系统 Excel 2016","summary":"工作表操作、公式与函数、格式化、数据处理和图表。","sections":[{"id":"4.1","title":"Excel 2016 概述"},{"id":"4.2","title":"Excel 2016 的基本操作"},{"id":"4.3","title":"Excel 公式与函数"},{"id":"4.4","title":"格式化工作表"},{"id":"4.5","title":"数据处理"},{"id":"4.6","title":"使用图表"}]},{"number":5,"title":"演示文稿软件 PowerPoint 2016","summary":"幻灯片组织、外观、动画、切换与放映设置。","sections":[{"id":"5.1","title":"PowerPoint 2016 基础"},{"id":"5.2","title":"幻灯片页面设计"},{"id":"5.3","title":"幻灯片页面外观的修饰"},{"id":"5.4","title":"动画效果和动作设置"},{"id":"5.5","title":"播放和打印演示文稿"},{"id":"5.6","title":"演示文稿的其他功能"}]},{"number":6,"title":"计算机网络及网页制作","summary":"网络结构、Internet应用、HTML、网页与信息检索。","sections":[{"id":"6.1","title":"计算机网络概述"},{"id":"6.2","title":"计算机网络系统"},{"id":"6.3","title":"Internet 基础和应用"},{"id":"6.4","title":"网页、网页制作及 HTML 简介"},{"id":"6.5","title":"信息检索"}]},{"number":7,"title":"数字多媒体技术基础","summary":"多媒体特征、媒体元素、图像格式、颜色和视频。","sections":[{"id":"7.1","title":"数字多媒体技术概述"},{"id":"7.2","title":"数字多媒体系统组成及常用软件"},{"id":"7.3","title":"常用多媒体制作软件"}]},{"number":8,"title":"信息安全","summary":"安全属性、恶意软件、防火墙、密码技术和信息伦理。","sections":[{"id":"8.1","title":"信息安全概述"},{"id":"8.2","title":"计算机病毒"},{"id":"8.3","title":"防火墙"},{"id":"8.4","title":"Windows 10 操作系统安全"},{"id":"8.5","title":"信息伦理"}]},{"number":9,"title":"信息技术前沿","summary":"虚拟现实、云计算、物联网、区块链与人工智能。","sections":[{"id":"9.1","title":"虚拟现实和增强现实"},{"id":"9.2","title":"云计算和高性能计算"},{"id":"9.3","title":"物联网技术"},{"id":"9.4","title":"大数据技术"},{"id":"9.5","title":"区块链技术"},{"id":"9.6","title":"人工智能"},{"id":"9.7","title":"量子通信"},{"id":"9.8","title":"元宇宙"}]},{"number":10,"title":"数据库技术基础","summary":"关系数据库、数据库管理系统、关系运算、SQL与NoSQL。","sections":[{"id":"10.1","title":"数据库技术基础"},{"id":"10.2","title":"数据库管理系统"},{"id":"10.3","title":"数据库设计与 NoSQL"}]},{"number":11,"title":"计算思维","summary":"计算思维、算法表示、算法特征和基本控制结构。","sections":[{"id":"11.1","title":"计算思维"},{"id":"11.2","title":"计算思维与算法"},{"id":"11.3","title":"算法的控制结构"},{"id":"11.4","title":"面向对象程序设计"},{"id":"11.5","title":"基础算法设计思想"}]}],"notes":[{"q":25,"chapter":10,"section":"10.1","type":"多选","topic":"关系运算","title":"选择、投影、连接与集合运算","trigger":"真题从WHERE对应、单表取行列、多表组合和“只属于一个集合”考查关系代数。","conclusion":"选择筛选行，投影取得列并按关系代数的集合语义去重，连接按匹配条件组合元组；并、交、差还要检查两侧关系是否相容。","points":["从人员表筛出男性使用选择，再只保留编号、姓名、性别使用投影；若需要全部人员的指定字段，不必额外增加行条件。","关系代数投影会消除所得重复元组；普通SQL SELECT默认可保留重复行，SELECT DISTINCT才去除结果行重复。","自然连接按所有同名属性相等匹配，公共属性在输出中只保留一列，其余属性保留；自然内连接不保留未匹配行。","连接不是按两表的显示行号一一拼接；同一个连接值若匹配多行，应产生所有匹配组合。要按指定字段连接时，应明确连接条件。","并、交、差要求两侧列数相同且对应列的域或数据类型相容；字段名或顺序不一致时要先明确对应关系，不能把任意两张表直接做集合运算。","S−T只保留属于S而不属于T的元组，方向不能颠倒；“仅属于两集合之一”是(S−T)∪(T−S)，不是单独的S−T。","跨表获取相关信息通常可理解为先连接，再按目标选择行、投影列；这是语义分析方式，不是强制数据库按同一物理顺序执行。"],"boundary":"关系代数的“选择”对应筛行，不等于SQL命令名SELECT的全部作用；投影去重、集合相容性和连接匹配条件都不能省略。","id":"merged-20","sources":[{"year":2020,"q":25,"type":"多选"},{"year":2023,"q":46,"type":"填空"},{"year":2024,"q":14,"type":"单选"},{"year":2026,"q":11,"type":"单选"},{"year":2022,"q":27,"type":"多选"},{"year":2021,"q":13,"type":"单选","page":3}],"keys":["2020-25","2023-46","2024-14","2026-11","2022-27","2021-13"],"comparison":{"headers":["运算","主要改变","易错边界"],"rows":[["选择σ","保留满足条件的行","列结构不因此减少"],["投影π","保留指定列","关系代数结果去重"],["自然连接⋈","组合所有同名属性相等的元组","不是按显示行号拼接"],["差S−T","保留S有而T没有的元组","有方向且要求关系相容"]]},"pointGroups":[{"title":"行、列与跨表匹配","indices":[0,1,2,3]},{"title":"集合运算与组合使用","indices":[4,5,6]}]},{"q":35,"chapter":10,"section":"10.1","type":"填空","topic":"SQL查询","title":"SELECT查询与字段选择","trigger":"两道题分别考查SQL查询命令和星号的含义。","conclusion":"SELECT指定结果列，FROM指定数据来源，WHERE筛选行，ORDER BY规定输出顺序；星号只代表来源中的全部列，不能据此断定全部行都会返回。","points":["基本结构可写为SELECT 字段 FROM 表 WHERE 条件 ORDER BY 字段；是否返回某行还取决于WHERE、连接及其他查询条件。","SELECT默认可能保留重复结果；需要去重时使用DISTINCT。GROUP BY用于分组，不应拿它代替单纯的去重或排序说明。","没有ORDER BY时，不保证按插入顺序、主键顺序或屏幕上原来的顺序返回。排序值相同且需要固定次序时，可追加学号等排序键。","WHERE只保留条件为真的行；NULL表示未知或缺失，判断它应写IS NULL或IS NOT NULL，不能写“= NULL”。","例如SELECT 姓名 FROM 学生 WHERE 成绩 &gt;= 60只返回达标学生姓名；成绩为NULL不自动等于0，也不会使该比较条件成立。","实际应用宜明确列出所需字段，减少无用传输并稳定结果结构；ORDER BY排列查询结果，不修改源表数据。"],"boundary":"SELECT *的星号表示所有列，不是所有行；NULL不是0或空字符串，结果排序也不等于更新源数据。","id":"merged-21","sources":[{"year":2020,"q":35,"type":"填空"},{"year":2026,"q":43,"type":"填空"}],"keys":["2020-35","2026-43"],"comparison":{"headers":["语句部分","作用"],"rows":[["SELECT 姓名,成绩","决定返回哪些列"],["WHERE 成绩 >= 60","决定保留哪些行"],["SELECT DISTINCT 性别","去除结果中的重复行"],["ORDER BY 成绩 DESC,学号 ASC","决定结果次序及同分时的次序"],["成绩 IS NULL","查找缺失成绩"]]}},{"q":14,"chapter":10,"section":"10.1","type":"单选","topic":"关系模型","title":"属性、域、候选码、主键与外键要分层判断","trigger":"题目要求辨认关系模型中属性取值范围、行和列的术语。","conclusion":"关系的一行称元组，一列对应属性，属性允许取值的集合称域；候选码还必须是能够唯一标识元组且不含多余属性的最小属性集合。","points":["关系模式描述关系名、属性及相关约束；当前表格显示的值只是一个关系实例，不能把它等同于域或模式。","超码能唯一标识元组；候选码是在超码中删去任何一个属性后都不再具有唯一标识能力的集合。这里的“最小”指没有冗余属性，不是所有候选码的属性数必须一样多。","从候选码中选一个作为主码；主码可以由多个属性联合构成。一张表至多声明一个主键，但这个主键可以包含多列。","例如选课关系可用“学号、课程号”共同标识一条选课；学号单独出现多次，不代表联合主键有重复。","SQL主键约束要求唯一且非空；普通UNIQUE约束对NULL的处理依数据库及设置而异，不能直接当成主键。","外键用于参照完整性，本列通常可以重复；它引用主键或受支持的唯一键，是否允许空值还取决于非空约束等设置。","候选码要由业务规则保证唯一，不能因为眼前几行姓名恰好没有重复，就断言姓名能永久作为候选码。"],"boundary":"域不是某一行或当前列中已经出现的值；候选码不只是“能唯一”的任意属性集合，也不是只能含一列。“字段/记录”与“属性/元组”应按表和关系模型语境区分。","id":"y2023q14","sources":[{"year":2023,"q":14,"type":"单选"}],"keys":["2023-14"],"comparison":{"headers":["概念","判断依据"],"rows":[["域","该属性允许出现哪些值"],["超码","能否唯一标识元组"],["候选码","唯一标识且不存在多余属性"],["主码","从候选码中选定，SQL约束要求唯一且非空"],["外键","非空引用值是否对应合法的被引用键"]]},"pointGroups":[{"title":"先分清域、超码与候选码","indices":[0,1,2]},{"title":"再检查联合主键、外键与业务规则","indices":[3,4,5,6]}]},{"q":15,"chapter":10,"section":"10.1","type":"单选","topic":"SQL更新","title":"UPDATE修改已有记录中的字段值","trigger":"题目要求选择用于修改关系表中已有数据的SQL命令。","conclusion":"UPDATE用于更新已有记录；SET指定新值，WHERE限定被修改的记录。","points":["基本形式为UPDATE 表名 SET 字段=值 WHERE 条件。","省略WHERE通常会更新表中所有记录。","INSERT添加记录，DELETE删除记录，ALTER修改表结构。"],"boundary":"执行更新前应先用相同WHERE条件查询核对；UPDATE改数据，不负责修改字段结构。","id":"y2023q15","sources":[{"year":2023,"q":15,"type":"单选"}],"keys":["2023-15"]},{"q":36,"chapter":10,"section":"10.1","type":"判断","topic":"SQL删除","title":"DELETE删除满足条件的记录，不删除表结构","trigger":"题目解释DELETE FROM student WHERE 班级=\"一班\"的作用。","conclusion":"DELETE FROM student WHERE 班级=&#39;一班&#39;删除符合条件的记录并保留表结构；省略WHERE会针对全部行，DROP TABLE才移除整个表对象。","points":["WHERE决定DELETE或UPDATE的作用行；条件没有命中时可影响0行，这本身不表示语法错误。","DELETE FROM student执行后，即使没有剩余记录，student的字段和表对象仍存在；DROP TABLE student后，再查询该表应报告表不存在。","UPDATE用SET改已有记录的字段值；INSERT增加记录；ALTER TABLE改变字段、约束等结构，不能把删列当成DELETE。","ALTER TABLE新增字段后，已有记录的新字段取默认值；未指定默认值时通常为NULL。增加非空字段时须考虑已有数据能否满足约束。","TRUNCATE清空整表并保留表对象，但支持情况、触发器和事务行为依DBMS而异；不能背成“所有数据库中都不可回滚”，例如PostgreSQL的TRUNCATE可随事务回滚。","真正执行仍受权限、外键约束和触发器等限制；某些删除可能被拒绝或触发级联，不能用命令名称保证它一定成功。"],"boundary":"字符串通常用单引号，规范示例写WHERE 班级=&#39;一班&#39;；删行、改值、增删字段与删整表是不同层级，执行前应核对对象和条件。","id":"y2024q36","sources":[{"year":2024,"q":36,"type":"判断"},{"year":2022,"q":46,"type":"填空"}],"keys":["2024-36","2022-46"],"comparison":{"headers":["命令","主要对象","典型结果"],"rows":[["SELECT","查询结果","读取数据"],["INSERT","新记录","行数增加，仍检查约束"],["UPDATE…SET…WHERE…","命中的已有记录","字段值改变"],["DELETE…WHERE…","命中的已有记录","行移除，表结构保留"],["ALTER TABLE","表定义","增加、移除或修改字段及约束"],["DROP TABLE","整个表对象","表及其数据不再存在"]]}},{"q":47,"chapter":10,"section":"10.1","type":"填空","topic":"SQL表结构","title":"ALTER TABLE用于修改已有表结构","trigger":"题目要求向已有数据表添加年龄字段。","conclusion":"可使用ALTER TABLE 表名 ADD 年龄 数据类型，向表中增加字段；具体数据类型和关键字细节由DBMS决定。","points":["ALTER修改数据库对象结构。","INSERT新增记录，UPDATE修改记录值。","添加非空字段时还要考虑已有记录的默认值。","CREATE TABLE创建表，ALTER TABLE修改表结构，DROP TABLE移除表；UPDATE修改已有记录的字段值，DELETE删除记录，层次不同。"],"boundary":"改表结构可能锁表或影响应用，生产环境应先评估兼容性、备份和迁移方案。","id":"y2024q47","sources":[{"year":2024,"q":47,"type":"填空"},{"year":2021,"q":35,"type":"填空","page":6}],"keys":["2024-47","2021-35"]},{"q":12,"chapter":10,"section":"10.1","type":"单选","topic":"SQL写入","title":"INSERT向表中添加新记录","trigger":"题目要求选择把新生记录加入信息表的SQL命令。","conclusion":"INSERT用于插入新记录；SELECT查询，DELETE删除记录，ALTER修改数据库对象结构。","points":["常见形式是INSERT INTO 表名(字段) VALUES(值)。","字段与值的数量、顺序和数据类型应对应。","主键、非空、唯一和外键约束仍会检查新记录。"],"boundary":"ALTER用于改表结构，不用于把普通记录追加到表中。","id":"y2025q12","sources":[{"year":2025,"q":12,"type":"单选"}],"keys":["2025-12"]},{"q":13,"chapter":10,"section":"10.2","type":"单选","topic":"数据库系统","title":"数据库、DBMS与数据库系统不是同一层级","trigger":"真题从Access、DBA、系统构成和核心软件关系考查数据库基本概念。","conclusion":"数据库是数据集合，DBMS是管理数据库的核心软件，数据库系统还包括应用、人员和运行环境；Access属于关系DBMS。","points":["DBMS负责定义、存取、控制、恢复和并发管理等。","DBA负责权限、备份恢复、性能与可用性。","数据库系统比文件系统提供更强的数据共享和一致性管理。"],"boundary":"DB、DBMS和DBS不能互换；应说DBMS是数据库系统的核心软件，而不是反过来。","id":"y2020q13","sources":[{"year":2020,"q":13,"type":"单选"},{"year":2023,"q":36,"type":"判断"},{"year":2024,"q":27,"type":"多选"}],"keys":["2020-13","2023-36","2024-27"]},{"q":42,"chapter":10,"section":"10.2","type":"填空","topic":"数据库人员","title":"数据库运维工作由数据库管理员负责","trigger":"题目在数据库管理人员分类中判断负责数据库运维的角色。","conclusion":"数据库管理员DBA负责数据库安装配置、权限、安全、备份恢复、性能监控和日常运行维护。","points":["系统分析员侧重需求与系统方案。","应用程序员负责开发访问数据库的业务程序。","DBA还需管理账户、容量、日志和故障恢复。"],"boundary":"DBA不是所有数据内容的业务负责人，权限与职责仍应分离。","id":"y2025q42","sources":[{"year":2025,"q":42,"type":"填空"}],"keys":["2025-42"]},{"q":14,"chapter":10,"section":"10.3","type":"单选","topic":"实体联系","title":"一对一、一对多和多对多联系要双向判断","trigger":"题目描述一个团支部有多名团员，而一个团员只属于一个团支部。","conclusion":"联系基数由业务规则决定：从两端分别判断一个实例最多可对应几个实例，再区分一对一、一对多与多对多。","points":["一对一表示双方每个实体最多对应另一方一个实体。","一对多常通过在“多”端保存“一”端主键作为外键实现。","多对多通常需要中间关联表拆成两个一对多。","判断联系必须双向看：一家出版社可向多家书店供书，一家书店也可向多家出版社进货，因此是多对多。具体基数取决于业务规则。"],"boundary":"关系方向会影响措辞，但不会改变结构本质；判断时分别看两端最大对应数量。","id":"y2020q14","sources":[{"year":2020,"q":14,"type":"单选"},{"year":2022,"q":13,"type":"单选"}],"keys":["2020-14","2022-13"]},{"q":26,"chapter":10,"section":"10.3","type":"多选","topic":"NoSQL与图数据库","title":"NoSQL按数据模型与访问需求选型","trigger":"真题从模型灵活性、查询语言、一致性取舍和社交关系网络选择考查NoSQL。","conclusion":"NoSQL常强调灵活模型与横向扩展；不同产品在一致性、可用性和扩展性间取舍，图数据库则适合多跳关联和路径分析。","points":["常见类型包括键值、文档、列族和图数据库。","NoSQL没有一套所有产品统一采用的标准查询语言。","选型还要评估事务、查询模式、数据结构和运维成本。","宽列/列族数据库是常见NoSQL模型之一；关系数据库也可采用列式存储，不能见到“按列存储”就断言一定是NoSQL。","模型灵活、水平扩展与大规模存储是许多NoSQL产品的适用方向；复杂查询能力、事务和一致性保证必须按具体产品判断，不是所有NoSQL都弱或都强。"],"boundary":"NoSQL不是“不查询”或“永远不要一致性”，图数据库也不是所有大数据场景的默认答案。","id":"y2026q12","sources":[{"year":2023,"q":26,"type":"多选"},{"year":2024,"q":15,"type":"单选"},{"year":2026,"q":12,"type":"单选"},{"year":2022,"q":35,"type":"判断"},{"year":2021,"q":27,"type":"多选","page":5}],"keys":["2023-26","2024-15","2026-12","2022-35","2021-27"]},{"q":11,"chapter":10,"section":"10.3","type":"单选","topic":"数据库设计","title":"数据库设计不因规模小而省略","trigger":"题目要求找出数据库设计阶段描述中的错误项。","conclusion":"数据库设计通常包括需求分析、概念结构、逻辑结构和物理结构等阶段，小型数据库同样需要与规模相称的设计。","points":["需求分析是后续设计的基础。","E-R图属于概念结构设计，通常不依赖具体DBMS。","存储方法、文件组织和索引等属于物理结构设计。","需求分析明确业务需求；概念结构设计建立E-R模型；逻辑结构设计转成关系模式；物理设计考虑索引、存储与访问组织。E-R图主要属于概念设计阶段。"],"boundary":"规模小可以简化文档和过程，但不能等同于“不需要设计”。","id":"y2025q11","sources":[{"year":2025,"q":11,"type":"单选"},{"year":2021,"q":14,"type":"单选","page":3}],"keys":["2025-11","2021-14"]}],"sourceCount":460,"years":[2020,2021,2022,2023,2024,2025,2026]};
window.NOTE_REFERENCES={"merged-20":[["Emory大学：选择、投影、笛卡尔积与连接","https://www.cs.emory.edu/~cheung/Courses/554/Syllabus/1-intro/intro4.html"],["PostgreSQL：连接条件、USING与自然连接","https://www.postgresql.org/docs/current/queries-table-expressions.html"],["PostgreSQL：并、交、差及相容性","https://www.postgresql.org/docs/current/queries-union.html"]],"merged-21":[["SQLite：SELECT的DISTINCT、WHERE与ORDER BY语义","https://www.sqlite.org/lang_select.html"],["PostgreSQL：比较运算与NULL判断","https://www.postgresql.org/docs/current/functions-comparison.html"]],"y2023q14":[["Emory大学：关系及超码、候选码、主码","https://www.cs.emory.edu/~cheung/Courses/554/Syllabus/1-intro/relation.html"],["PostgreSQL：主键、唯一与外键约束","https://www.postgresql.org/docs/current/ddl-constraints.html"]],"y2024q36":[["PostgreSQL：DELETE","https://www.postgresql.org/docs/current/sql-delete.html"],["PostgreSQL：UPDATE","https://www.postgresql.org/docs/current/sql-update.html"],["PostgreSQL：DROP TABLE","https://www.postgresql.org/docs/current/sql-droptable.html"],["PostgreSQL：ALTER TABLE及新增字段默认值","https://www.postgresql.org/docs/current/ddl-alter.html"],["PostgreSQL：TRUNCATE的事务与约束行为","https://www.postgresql.org/docs/current/sql-truncate.html"]]};
window.NOTE_DEMOS={"y2023q15":{"kind":"sequence","title":"安全更新一名学生的班级","task":"先用SELECT预览命中范围，再执行带WHERE的UPDATE并复查。","steps":[{"label":"先查询WHERE学号=2023008","detail":"确认只命中目标学生。"},{"label":"编写UPDATE student","detail":"指定要修改的表。"},{"label":"SET 班级='临床2班'","detail":"给目标字段赋新值。"},{"label":"保留WHERE 学号='2023008'","detail":"避免无条件更新全表。"},{"label":"执行并再次SELECT","detail":"确认一行更新且其他记录未变。"}]},"y2024q47":{"kind":"sequence","title":"安全地给学生表增加年龄列","task":"在SQL工作台中检查结构、执行ALTER并验证结果。","steps":[{"label":"查看现有表结构","detail":"确认字段名、命名规则和兼容性。"},{"label":"编写ALTER TABLE","detail":"写ALTER TABLE student ADD 年龄 INT。"},{"label":"执行并处理已有记录","detail":"新增列后旧记录通常先为NULL或使用默认值。"},{"label":"查询结构验证","detail":"确认字段类型、约束和应用读写都正常。"}]},"y2025q12":{"kind":"sequence","title":"向新生信息表插入一行","task":"在SQL工作台中组装并执行INSERT语句。","steps":[{"label":"选择目标表与字段","detail":"明确写入新生信息表的学号、姓名等列。"},{"label":"填写VALUES","detail":"值的数量、顺序和数据类型与字段对应。"},{"label":"执行INSERT","detail":"数据库检查主键、非空和外键约束。"},{"label":"查询验证","detail":"用SELECT确认新记录已经写入。"}]},"y2020q13":{"kind":"explore","title":"分清数据库与DBMS","task":"点击对象，观察它是数据集合、管理软件还是数据模型。","initial":"Access是关系数据库管理系统。","actions":[{"label":"一个.accdb文件","stage":"数据库","result":"保存表、查询等数据库对象和数据。","tone":"good"},{"label":"Microsoft Access","stage":"数据库管理系统DBMS","result":"用于创建、维护和访问数据库。","tone":"good"},{"label":"二维表及其关系","stage":"关系模型","result":"用字段、记录、主键和联系组织数据。","tone":"good"},{"label":"Word表格","stage":"不是关系数据库的充分条件","result":"看起来是二维表不代表具备数据库约束与管理能力。","tone":"warn"}]},"y2025q42":{"kind":"explore","title":"进入DBA值班台","task":"点击一次数据库事件，判断该由哪个角色负责。","initial":"生产数据库正在运行。","actions":[{"label":"定时备份与恢复演练","stage":"数据库管理员DBA","result":"保障故障后可恢复。","tone":"good"},{"label":"账户与权限审计","stage":"数据库管理员DBA","result":"落实最小权限和追踪。","tone":"good"},{"label":"设计业务需求流程","stage":"系统分析员主导","result":"职责侧重需求与方案。","tone":"warn"},{"label":"开发挂号页面","stage":"应用程序员主导","result":"通过程序访问数据库。","tone":"warn"}]},"y2026q12":{"kind":"explore","title":"给数据场景选模型","task":"点击需求，观察NoSQL与关系数据库各自的取舍。","initial":"选型要看数据结构、事务、查询和扩展需求。","actions":[{"label":"字段经常变化的文档","stage":"文档型NoSQL较灵活","result":"同一集合中的文档结构可不完全一致。","tone":"good"},{"label":"海量键值高速访问","stage":"键值数据库适合","result":"按键直接读写，模型简单。","tone":"good"},{"label":"复杂事务与多表约束","stage":"关系数据库通常更自然","result":"成熟SQL、事务和约束能力是优势。","tone":"good"},{"label":"NoSQL一定更快且无一致性","stage":"错误绝对化","result":"性能和一致性取决于具体产品、配置与负载。","tone":"bad"}]},"y2025q11":{"kind":"sequence","title":"把需求逐层变成数据库","task":"按设计阶段把“新生信息系统”从业务语言落到存储结构。","steps":[{"label":"需求分析","detail":"确认要管理谁、做什么查询和遵守哪些业务规则。"},{"label":"概念结构设计","detail":"用E-R图表达实体、属性和联系，不绑定具体DBMS。"},{"label":"逻辑结构设计","detail":"转换为关系表、主键、外键和约束。"},{"label":"物理结构设计","detail":"选择文件组织、索引和具体存储方法。"}]}};
